Vector2 PushOut(Box mover, Box wall)
{
    float overlapX = MathF.Min(mover.MaxX, wall.MaxX) - MathF.Max(mover.MinX, wall.MinX);
    float overlapY = MathF.Min(mover.MaxY, wall.MaxY) - MathF.Max(mover.MinY, wall.MinY);
    if (overlapX <= 0 || overlapY <= 0) return new Vector2(0, 0);   // not touching

    bool moverIsLeft = mover.MinX + mover.MaxX < wall.MinX + wall.MaxX;
    bool moverIsBelow = mover.MinY + mover.MaxY < wall.MinY + wall.MaxY;
    if (overlapX < overlapY) return new Vector2(moverIsLeft ? -overlapX : overlapX, 0);
    return new Vector2(0, moverIsBelow ? -overlapY : overlapY);
}

