Esta es una versión mínima del modelo de Unity, que se usa en los fragmentos siguientes. En cada frame el juego llama a `Update(dt)` de cada objeto, que lo llama en cada uno de sus componentes:

```csharp
public abstract class Component
{
    public GameObject Owner { get; set; } = null!;
    public virtual void Update(float dt) { }
}

public class GameObject
{
    readonly List<Component> components = new();
    public string Name { get; }
    public Vector2 Position { get; set; }

    public GameObject(string name) => Name = name;

    public T Add<T>(T component) where T : Component
    {
        component.Owner = this;
        components.Add(component);
        return component;
    }

    public T? Get<T>() where T : Component => components.OfType<T>().FirstOrDefault();

    public void Update(float dt)
    {
        foreach (var c in components) c.Update(dt);
    }
}
```

En Unity, la posición vive en un componente `Transform` y `GetComponent<T>()` hace el papel de `Get<T>()`.

