Los mismos pasos en C#, sobre un mapa de 5×5 donde `#` es una pared:

```csharp
string[] map =
{
    "S.#..",
    "..#..",
    "....G",
    ".###.",
    ".....",
};
Console.WriteLine(Steps(map));

int Steps(string[] map)
{
    var start = (r: 0, c: 0);                    // S is in the top-left corner
    var dist = new Dictionary<(int r, int c), int> { [start] = 0 };
    var frontier = new Queue<(int r, int c)>();
    frontier.Enqueue(start);

    while (frontier.Count > 0)
    {
        var (r, c) = frontier.Dequeue();         // oldest tile first
        if (map[r][c] == 'G') return dist[(r, c)];
        foreach (var (nr, nc) in new[] { (r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1) })
        {
            bool open = nr >= 0 && nr < map.Length && nc >= 0 && nc < map[nr].Length && map[nr][nc] != '#';
            if (open && !dist.ContainsKey((nr, nc)))   // not visited yet
            {
                dist[(nr, nc)] = dist[(r, c)] + 1;
                frontier.Enqueue((nr, nc));
            }
        }
    }
    return -1;                                   // no path
}
```

Imprime `6`. Un `Dictionary` guarda la distancia de cada casilla visitada, así que “visitada” simplemente significa “tiene una distancia”.

